#include <pcosynchro/pcothread.h>
#include <vector>
#include <cstdlib>

#define NUM_THREADS 24

std::vector<PcoThread*> threads(NUM_THREADS);

bool doSomeWork() {
    int diceRoll = rand() % 20 + 1;
    if (diceRoll == 20) {
        return true;
    } else {
        return false;
    }
}

void threadFunction() {
    while (true) {
        bool finished = doSomeWork();
        if (finished) {
            for (auto& t : threads) {
                t->requestStop();
            }
        }
        if (PcoThread::thisThread()->stopRequested()) {
            return;
        }
    }
}

int main() {
    for (auto& t : threads) {
        t = new PcoThread(threadFunction);
    }
    for (auto& t : threads) {
        t->join();
        delete t;
    }
    return 0;
}

