Voici une solution complète avec un verrou par joueur **ordonné par `id`** (ce qui évite tout interblocage croisé et tout auto-blocage quand `target == this`) ainsi qu'un sémaphore de barrière au démarrage :

```cpp
PcoSemaphore startSem(0);

class Player {
public:
    Player(int id, int health, int mana)
        : id(id), health(health), mana(mana), mutex(1),
          thread(std::make_unique<PcoThread>(&Player::run, this)) {}

    enum class Action {attack, heal, leave, nothing};

    void lockPair(Player* other) {
        if (this == other) {
            this->mutex.acquire();
        } else if (this->id < other->id) {
            this->mutex.acquire();
            other->mutex.acquire();
        } else {
            other->mutex.acquire();
            this->mutex.acquire();
        }
    }

    void unlockPair(Player* other) {
        if (this == other) {
            this->mutex.release();
        } else {
            this->mutex.release();
            other->mutex.release();
        }
    }

    void attack(Player* player) {
        lockPair(player);
        if (health > 0) {
            int damage = rand() % 12 + 1;
            player->health -= damage;
        }
        unlockPair(player);
    }

    void heal(Player* target) {
        lockPair(target);
        if (health > 0) {
            int h = rand() % 6 + 1;
            target->health += h;
            this->mana -= 10;
        }
        unlockPair(target);
    }

    bool isAlive() {
        mutex.acquire();
        bool alive = (health > 0);
        mutex.release();
        return alive;
    }

    void run() {
        /* 2. Attendre que tous les joueurs soient créés */
        startSem.acquire();

        while (isAlive()) {
            Player* target = get_target();
            Action action = get_action();

            switch (action) {
                case Action::attack: attack(target); break;
                case Action::heal:   heal(target); break;
                case Action::leave:  return;
                default: break;
            }
            PcoThread::usleep(1000000);
        }
    }

    int id;
    int health;
    int mana;
    PcoSemaphore mutex;
    std::unique_ptr<PcoThread> thread;
};

std::vector<std::unique_ptr<Player>> players;

int main() {
    for (int i = 0; i < 10; ++i) {
        players.push_back(std::make_unique<Player>(i, rand() % 100 + 50, rand() % 100 + 20));
    }

    /* Débloque les 10 threads une fois tous les joueurs créés */
    for (size_t i = 0; i < players.size(); ++i) {
        startSem.release();
    }

    for (auto& player : players) {
        player->thread->join();
    }

    return 0;
}
```

*(Note : Utiliser un unique `PcoSemaphore globalMutex(1)` pour protéger `health`/`mana` et `rand()` est également une solution valide sans risque d'interblocage, au prix d'une moindre parallélisation entre actions.)*

```cpp
PcoSemaphore mutex(1);
PcoSemaphore attente(0);
int nbParticipants = 0;
int numGroupe = 1;

int depart() {
    mutex.acquire();
    nbParticipants++;
    int monGroupe = numGroupe;

    if (nbParticipants < 5) {
        mutex.release();
        attente.acquire();
    } else {
        nbParticipants = 0;
        numGroupe++;
        for (int i = 0; i < 4; ++i) {
            attente.release();
        }
        mutex.release();
    }

    return monGroupe;
}
```

**Points clés :**
* Chaque thread mémorise `monGroupe` **avant** de libérer `mutex`, afin que l'incrémentation de `numGroupe` pour le groupe suivant ne modifie pas la valeur retournée aux threads du groupe courant.
* Le 5e thread remet `nbParticipants = 0`, incrémente `numGroupe`, réveille exactement les 4 threads en attente via `attente.release()` puis libère `mutex`.
* *(Remarque avancée : si un thread des 4 premiers est préempté exactement entre `mutex.release()` et `attente.acquire()`, un thread du groupe suivant pourrait consommer un jeton d'attente ; pour éliminer même ce cas extrême, on peut utiliser une barrière réutilisable à deux phases avec un second sémaphore.)*

